  border-radius: var(--wp--preset--border-radius--full);
  background-color: var(--wp--preset--color--neutral-200);
  border: 2px solid #0000;
  flex-shrink: 0;
  align-items: center;
  width: 2.25rem;
  height: 1.25rem;
  transition: colors .2s;
  display: inline-flex;
}

.dark .switch-root {
  background-color: var(--wp--preset--color--neutral-800);
}

.switch-root:focus-visible {
  border-color: var(--wp--preset--color--neon-purple);
  box-shadow: 0 0 0 1px var(--wp--preset--color--neon-purple);
  outline: none;
}

.switch-root:disabled {
  cursor: not-allowed;
  opacity: .5;
}

.switch-root[data-state="checked"] {
  background-color: var(--wp--preset--color--neon-purple);
}

.switch-thumb {
  background-color: var(--wp--preset--color--base);
  border-radius: 50%;
  width: 1rem;
  height: 1rem;
  transition: transform .2s;
  display: block;
  transform: translateX(0);
  box-shadow: 0 2px 4px #0003;
}

.switch-root[data-state="checked"] .switch-thumb {
  transform: translateX(1rem);
}

.form-item {
  gap: .5rem;
  display: grid;
}

.form-label-error {
