.toggle {
  border-radius: var(--wp--preset--border-radius--md);
  color: var(--wp--preset--color--neutral-600);
  cursor: pointer;
  background-color: #0000;
  border: 1px solid #0000;
  justify-content: center;
  align-items: center;
  font-size: .875rem;
  font-weight: 500;
  transition: all .2s;
  display: inline-flex;
}

.dark .toggle {
  color: var(--wp--preset--color--neutral-400);
}

.toggle:hover {
  background-color: var(--wp--preset--color--neutral-100);
  color: var(--wp--preset--color--neutral-800);
}

.dark .toggle:hover {
  background-color: var(--wp--preset--color--neutral-800);
  color: var(--wp--preset--color--neutral-200);
}

.toggle[data-state="on"] {
  background-color: var(--wp--preset--color--neutral-200);
  color: var(--wp--preset--color--contrast);
}

.dark .toggle[data-state="on"] {
  background-color: var(--wp--preset--color--neutral-700);
  color: #fff;
}

.toggle:focus-visible {
  box-shadow: 0 0 0 2px var(--wp--preset--color--neon-purple);
  outline: none;
}

.toggle:disabled {
