}

.toggle-group-item:first-child {
  border-top-left-radius: var(--wp--preset--border-radius--md);
  border-bottom-left-radius: var(--wp--preset--border-radius--md);
}

.toggle-group-item:last-child {
  border-top-right-radius: var(--wp--preset--border-radius--md);
  border-bottom-right-radius: var(--wp--preset--border-radius--md);
}

.toggle-group[data-variant="outline"] {
