.collapsible {
  width: 100%;
}

.collapsible-trigger {
  cursor: pointer;
  border-radius: var(--wp--preset--border-radius--md);
  width: 100%;
  color: inherit;
  background: none;
  border: none;
  justify-content: space-between;
  align-items: center;
  padding: .5rem;
  font-size: .875rem;
  font-weight: 500;
  display: flex;
}

.collapsible-trigger:hover {
  background-color: var(--wp--preset--color--neutral-100);
}

.dark .collapsible-trigger:hover {
  background-color: var(--wp--preset--color--neutral-800);
}

.collapsible-content {
  font-size: .875rem;
  overflow: hidden;
}

.collapsible-content[data-state="open"] {
