}

.collapsible-content[data-state="closed"] {
  animation: .2s ease-out collapsible-up;
}

@keyframes collapsible-down {
  from {
    opacity: 0;
    height: 0;
  }

  to {
    height: var(--radix-collapsible-content-height);
    opacity: 1;
  }
}

@keyframes collapsible-up {
  from {
    height: var(--radix-collapsible-content-height);
    opacity: 1;
  }

  to {
    opacity: 0;
    height: 0;
  }
}

