  --ebook-section-title-size: 1.25rem;
  --ebook-chapter-number-size: .8rem;
  --ebook-chapter-start-title-size: 1.5rem;
  --ebook-chapter-start-subtitle-size: 1rem;
  --ebook-part-label-size: .8rem;
  --ebook-part-title-size: 1.625rem;
  --ebook-part-subtitle-size: .95rem;
  --ebook-epigraph-size: 1.1rem;
  --ebook-epigraph-attr-size: .9rem;
  --ebook-page-number-size: .75rem;
  --ebook-page-pad-v: 1rem;
  --ebook-page-pad-h: 1rem;
  --ebook-meta-size: .8rem;
  --ebook-chapter-heading-size: .725rem;
  --ebook-blurb-size: 1.05rem;
  --ebook-status-size: .725rem;
  --ebook-back-title-size: 1.3rem;
  --ebook-dedication-size: 1.1rem;
  flex-direction: column;
  width: 100%;
  margin: 0 auto;
  display: flex;
  overflow: hidden;
}

.dark .ebook-reader {
  background: var(--wp--preset--color--atomic-black);
